Lemma lapi_1RB1LD_0LB1RC_0LA1RC_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
