(** ** The lap *)

Lemma lap_1RB1LD_0LB1RC_0LA1RC_1LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LB1RC_0LA1RC_1LA0RC B0_1RB1LD_0LB1RC_0LA1RC_1LA0RC B1_1RB1LD_0LB1RC_0LA1RC_1LA0RC 4 6 p j' [] []).
    + exact run_ovf_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j' E).
    + exact (geo_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_0LB1RC_0LA1RC_1LA0RC : stepn tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC 3 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_0LB1RC_0LA1RC_1LA0RC : existsb (fun tg => cfires tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC c0 3 tg) pins_1RB1LD_0LB1RC_0LA1RC_1LA0RC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LB1RC_0LA1RC_1LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LD_0LB1RC_0LA1RC_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LD_0LB1RC_0LA1RC_1LA0RC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LD_0LB1RC_0LA1RC_1LA0RC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_0LB1RC_0LA1RC_1LA0RC : forall t, ~ In t pins_1RB1LD_0LB1RC_0LA1RC_1LA0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_0LB1RC_0LA1RC_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LD_0LB1RC_0LA1RC_1LA0RC (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LD_0LB1RC_0LA1RC_1LA0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

Theorem qhtr_1RB1LD_0LB1RC_0LA1RC_1LA0RC : NonHalt tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC /\ QHBoundTr 32779478 tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC /\ QuasiHaltsTr tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
Proof.
  apply (lap_qh_stage tm_1RB1LD_0LB1RC_0LA1RC_1LA0RC pins_1RB1LD_0LB1RC_0LA1RC_1LA0RC Cc 1 3 32779478).
  - exact bootq_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
  - intros p _. apply lap_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
  - intros t Ht p _. apply fire_1RB1LD_0LB1RC_0LA1RC_1LA0RC. exact Ht.
  - exact wit_1RB1LD_0LB1RC_0LA1RC_1LA0RC.
  - apply qcleb_QC_24. reflexivity.
Qed.

