(** ** The lap *)

Lemma lap_1RB1LD_0LC0RB_1LD1RC_1LA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
