  - destruct (lapi_1RB1LD_0LC0RB_1LD1RC_1LA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
