    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC0RB_1LD1RC_1LA1LC B0_1RB1LD_0LC0RB_1LD1RC_1LA1LC B1_1RB1LD_0LC0RB_1LD1RC_1LA1LC 4 10 p j' [] []).
