    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LC0RB_1LD1RC_1LA1LC p j' E).
    + exact (geo_1RB1LD_0LC0RB_1LD1RC_1LA1LC p j' E).
    + lia.
