(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_0LC0RD_1LD0RB_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB1LD_0LC0RD_1LD0RB_1LA0RB.
